Demo.Run<object[]>(async demo =>
{
    await demo.SyncAsync();
    await using var scope = demo.Scope();
    var roles = scope.ServiceProvider.GetRequiredService<RoleStore<ShopDb>>();

    var created = await roles.UpsertAsync(new RoleUpsert { Code = "clerk", Title = "Clerk", Patterns = ["shop:orders:*"] });

    var db = scope.ServiceProvider.GetRequiredService<ShopDb>();
    await db.SyncUserRolesAsync(7, [created.Data!.Id]);
    await db.SaveChangesAsync();

    var set = await scope.ServiceProvider.GetRequiredService<IPermResolver>().ResolveAsync(7);

    return [created.Status, $"view orders: {set.Has("shop:orders:view")}", $"view users: {set.Has("shop:users:view")}"];
});

