Demo.Run<object[]>(async demo =>
{
    await using var scope = demo.Scope();
    var sessions = scope.ServiceProvider.GetRequiredService<ISessionStore>();

    var opened = await sessions.OpenAsync(7, new SessionClient { Kind = ClientKind.Web, Name = "Firefox" });
    var touched = await sessions.TouchAsync(opened.Id, opened.Key);
    var revoked = await sessions.RevokeAsync(opened.Id, IdentityCodes.SessionReason.AdminRevoked, byUserId: 99);
    var after = await sessions.TouchAsync(opened.Id, opened.Key);

    return [touched, revoked, after];
});

Demo.Run<object[]>(async demo =>
{
    await using var scope = demo.Scope();
