    db.Entity<IdentityApp>().Add(new IdentityApp { Code = "pending", Title = "Pending", CreateDate = Demo.Now });

    var written = await scope.ServiceProvider.GetRequiredService<ISecLog>().WriteAsync(new SecLogEntry
    {
